// Extract the ElevenLabs webhook tool payload (error-tolerant)
const out = { query: '', context: '', conversation_id: '', ok: true, error: '' };
try {
  const b = $json.body || $json;
  out.query = String(b.query || b.action || b.request || b.text || '').slice(0, 1000);
  out.context = String(b.context || b.notes || '').slice(0, 1000);
  out.conversation_id = String(b.conversation_id || '');
} catch (e) { out.error = String(e); }
if (!out.query.trim()) { out.ok = false; out.error = 'No query field found. Configure the ElevenLabs webhook tool to send { query, context }.'; }
return [{ json: out }];

// Build the JSON ElevenLabs reads out; never crash the webhook
let text = '';
try {
  const items = $input.all();
  const last = items[items.length - 1].json;
  text = last.output || last.text || last.voice_reply || last.result || '';
} catch (e) {}
if (!text) text = "Hmm, that didn't come back clean. Try saying it again.";
text = String(text).replace(/[*_#`>]/g, '').replace(/https?:\/\/\S+/g, 'the link in the description').slice(0, 400);
return [{ json: { result: text, spoken: text } }];
